const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
function daysAgo(n){const d=new Date(); d.setDate(d.getDate()-n);return dateInput(d)}
function dateInput(d){const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`}
function todayISO(){return dateInput(new Date())}
function dateDiff(a,b){const d1=new Date(a+'T12:00:00'),d2=new Date(b+'T12:00:00');return Math.max(0,Math.floor((d2-d1)/86400000))}
function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
const state={meds:[],purchases:[],reminders:[],lists:[],listId:null,movements:[],page:'inicio',filter:'todos',client:null,user:null,remote:false,telegramEnabled:false,authMode:'login',sessionReady:false};
function setDrawer(open){const sidebar=$('#sidebar'),backdrop=$('#drawer-backdrop');sidebar.classList.toggle('open',open);backdrop.classList.toggle('open',open);backdrop.setAttribute('tabindex',open?'0':'-1');document.body.classList.toggle('drawer-open',open);$('#mobile-menu').setAttribute('aria-expanded',String(open));}
function closeDrawer(){setDrawer(false)}
function uid(){return globalThis.crypto?.randomUUID?.()||`id-${Date.now()}-${Math.random().toString(16).slice(2)}`}
function getRemaining(m){const anchor=Number.isFinite(+m.baseRemaining)?+m.baseRemaining:Number(m.initial)||0;const sinceBase=dateDiff(m.baseDate||todayISO(),todayISO());const pauseOffset=Number(m.pausedDaysOffset)||0;return Math.max(0,anchor-(m.paused?0:Math.max(0,sinceBase-pauseOffset)*(+m.daily||0)))}
function getDays(m){return +m.daily>0?getRemaining(m)/+m.daily:Infinity}
function unit(m){return m.unit||'unidades'}
function fmtQty(n){return Number.isInteger(n)?String(n):n.toLocaleString('pt-BR',{maximumFractionDigits:1})}
function daysText(n){if(!Number.isFinite(n))return 'Sem previsão';if(n<=0)return 'Estoque zerado';if(n<1)return 'Menos de 1 dia';return `${Math.floor(n)} ${Math.floor(n)===1?'dia':'dias'}`}
function needsPrescription(m){return m.needsPrescription===true}
function hasPrescriptionAlert(m){return needsPrescription(m)&&getDays(m)<=Number(m.prescriptionDays||0)}
function needsAttention(m){return getDays(m)<=Number(m.lowDays||0)||hasPrescriptionAlert(m)}
function statusFor(m){let d=getDays(m);if(d<=m.lowDays)return {label:d<=1?'Acabando':'Estoque baixo',cls:'critical'};if(hasPrescriptionAlert(m))return {label:'Pedir receita',cls:'warn'};return {label:'Em dia',cls:''}}
function dateLong(d=new Date()){return new Intl.DateTimeFormat('pt-BR',{weekday:'long',day:'numeric',month:'long'}).format(d)}
function updateHeader(){let hour=new Date().getHours();const first=(state.user?.user_metadata?.full_name||state.user?.email||'').split(/[ @]/)[0]||'Olá';$('#greeting').innerHTML=`${hour<12?'Bom dia':hour<18?'Boa tarde':'Boa noite'}, ${esc(first)} <span>${hour<12?'☀':hour<18?'◒':'☾'}</span>`;$('#today').textContent=new Intl.DateTimeFormat('pt-BR',{day:'2-digit',month:'short'}).format(new Date());$('#long-date').textContent=dateLong();$('#nav-count').textContent=state.meds.length;const reminderCount=state.reminders.filter(r=>r.status==='pending').length;const reminderBadge=$('#reminder-count');if(reminderBadge)reminderBadge.textContent=reminderCount;const needs=state.meds.some(needsAttention);$('#alert-dot').classList.toggle('hidden',!needs)}
function persist(){if(state.remote){saveRemote();return}localStorage.setItem('minhaFarmaciaMeds',JSON.stringify(state.meds));localStorage.setItem('minhaFarmaciaPurchases',JSON.stringify(state.purchases));localStorage.setItem('minhaFarmaciaReminders',JSON.stringify(state.reminders));localStorage.setItem('minhaFarmaciaMovements',JSON.stringify(state.movements));localStorage.setItem('minhaFarmaciaLists',JSON.stringify(state.lists));localStorage.setItem('minhaFarmaciaListId',state.listId||'')}
function loadLocal(){try{const raw=localStorage.getItem('minhaFarmaciaMeds');state.meds=raw?JSON.parse(raw):[];state.purchases=JSON.parse(localStorage.getItem('minhaFarmaciaPurchases')||'[]');state.reminders=JSON.parse(localStorage.getItem('minhaFarmaciaReminders')||'[]');state.movements=JSON.parse(localStorage.getItem('minhaFarmaciaMovements')||'[]');state.lists=JSON.parse(localStorage.getItem('minhaFarmaciaLists')||'[]')}catch{state.meds=[];state.purchases=[];state.lists=[]}if(!state.lists.length){state.lists=[{id:'local-default',name:'Minha lista'}];state.listId='local-default';state.meds=state.meds.map(m=>({...m,listId:'local-default'}));}state.listId=localStorage.getItem('minhaFarmaciaListId')||state.listId||state.lists[0]?.id;state.meds=state.meds.map(m=>({...m,needsPrescription:m.needsPrescription===true,baseRemaining:Number.isFinite(+m.baseRemaining)?+m.baseRemaining:Number(m.initial)||0,baseDate:m.baseDate||m.startedAt||todayISO()}))}
let syncQueue=Promise.resolve();
function saveRemote(){if(!state.client||!state.user)return Promise.resolve();syncQueue=syncQueue.then(async()=>{for(const l of state.lists){const row={user_id:state.user.id,name:l.name};if(!String(l.id).startsWith('local-'))row.id=l.id;const {data,error}=await state.client.from('medication_lists').upsert(row).select('id').single();if(error)throw error;l.id=data.id;if(l.id===state.listId)localStorage.setItem('minhaFarmaciaListId',l.id)}for(const m of state.meds){const row={user_id:state.user.id,list_id:state.listId,name:m.name,presentation:m.presentation||'',unit:m.unit||'unidades',initial_quantity:Number(m.initial)||0,base_remaining:Number(m.baseRemaining)||0,daily_consumption:Number(m.daily)||0,base_date:m.baseDate||todayISO(),started_at:m.startedAt||m.baseDate||todayISO(),prescription_days:Number(m.prescriptionDays)||0,needs_prescription:needsPrescription(m),low_stock_days:Number(m.lowDays)||0,paused:!!m.paused,paused_days_offset:Number(m.pausedDaysOffset)||0,color:m.color||''};if(m.remoteId)row.id=m.remoteId;const {data,error}=await state.client.from('medications').upsert(row).select('id').single();if(error)throw error;m.remoteId=data.id;m.localId=m.localId||m.id;m.id=data.id}for(const r of state.reminders){const med=state.meds.find(m=>m.id===r.medId||m.remoteId===r.medId||m.localId===r.medId);if(!med?.remoteId)continue;const row={user_id:state.user.id,list_id:state.listId,medication_id:med.remoteId,kind:r.kind,status:r.status,is_eligible:!!r.isEligible,last_notified_at:r.lastNotifiedAt||null,completed_at:r.completedAt||null};if(r.remoteId)row.id=r.remoteId;const {data,error}=await state.client.from('medication_reminders').upsert(row,{onConflict:'medication_id,kind'}).select('id').single();if(error)throw error;r.remoteId=data.id;r.medId=med.id}for(const x of state.purchases){const med=state.meds.find(m=>m.id===x.medId||m.remoteId===x.medId||m.localId===x.medId);if(!med?.remoteId)throw new Error(`Medicamento da compra não sincronizado: ${x.medName||''}`);const row={user_id:state.user.id,medication_id:med.remoteId,quantity:Number(x.quantity),purchased_at:x.purchasedAt||todayISO(),price:x.price?Number(x.price):null,notes:x.notes||''};if(x.remoteId)row.id=x.remoteId;const {data,error}=await state.client.from('purchases').upsert(row).select('id').single();if(error)throw error;x.remoteId=data.id}}).catch(e=>toast(`Falha ao sincronizar: ${e.message}`,true));return syncQueue}
async function migrateLocalDataOnce(){if(localStorage.getItem('minhaFarmaciaMigrated')==='true')return;if(state.meds.length)return;const localMeds=JSON.parse(localStorage.getItem('minhaFarmaciaMeds')||'[]');if(localMeds.length){state.meds=localMeds.map(m=>({...m,localId:m.id,listId:state.listId}));state.purchases=JSON.parse(localStorage.getItem('minhaFarmaciaPurchases')||'[]').map(x=>({...x,localId:x.id,listId:state.listId}));state.reminders=JSON.parse(localStorage.getItem('minhaFarmaciaReminders')||'[]');await saveRemote()}localStorage.setItem('minhaFarmaciaMigrated','true')}
async function ensureRemoteList(){if(state.lists.length)return;const {data,error}=await state.client.from('medication_lists').insert({user_id:state.user.id,name:'Minha lista'}).select('*').single();if(error)throw error;state.lists=[{id:data.id,name:data.name}];state.listId=data.id;localStorage.setItem('minhaFarmaciaListId',data.id)}
async function loadRemote(){const {data:ls,error:le}=await state.client.from('medication_lists').select('id,name,created_at').order('created_at');if(le)throw le;state.lists=(ls||[]).map(x=>({id:x.id,name:x.name}));await ensureRemoteList();const remembered=localStorage.getItem('minhaFarmaciaListId');state.listId=state.lists.some(l=>l.id===remembered)?remembered:state.lists[0].id;localStorage.setItem('minhaFarmaciaListId',state.listId);const {data:rows,error}=await state.client.from('medications').select('*').eq('list_id',state.listId).order('created_at');if(error)throw error;state.meds=(rows||[]).map(r=>({...r,remoteId:r.id,id:r.id,localId:r.id,baseRemaining:Number(r.base_remaining??r.baseRemaining??r.initial_quantity??r.initial??0),baseDate:r.base_date||r.baseDate||r.started_at||todayISO(),initial:Number(r.initial_quantity??r.initial??0),daily:Number(r.daily_consumption??r.daily??0),prescriptionDays:Number(r.prescription_days??r.prescriptionDays??14),needsPrescription:r.needs_prescription??r.needsPrescription??false,lowDays:Number(r.low_stock_days??r.lowDays??7),paused:r.paused||false,pausedDaysOffset:Number(r.paused_days_offset)||0,unit:r.unit||'unidades',presentation:r.presentation||''}));const medIds=state.meds.map(m=>m.remoteId);if(!medIds.length){state.purchases=[];state.reminders=[];state.movements=[];return}const {data:p,error:e}=await state.client.from('purchases').select('*').in('medication_id',medIds).order('purchased_at',{ascending:false});if(e)throw e;state.purchases=(p||[]).map(x=>({...x,id:`remote-${x.id}`,remoteId:x.id,medId:state.meds.find(m=>m.remoteId===x.medication_id)?.id||x.medication_id,quantity:x.quantity,purchasedAt:x.purchased_at,price:x.price,notes:x.notes}));const {data:r,error:re}=await state.client.from('medication_reminders').select('*').in('medication_id',medIds).order('created_at',{ascending:false});if(re)throw re;state.reminders=(r||[]).map(x=>({...x,id:x.id,remoteId:x.id,medId:state.meds.find(m=>m.remoteId===x.medication_id)?.id||x.medication_id,kind:x.kind,status:x.status,isEligible:!!x.is_eligible,lastNotifiedAt:x.last_notified_at,completedAt:x.completed_at}));const {data:mv,error:me}=await state.client.from('stock_movements').select('*').eq('list_id',state.listId).order('occurred_at',{ascending:false});if(me)throw me;state.movements=(mv||[]).map(x=>({...x,medName:x.medication_name,occurredAt:x.occurred_at}));}
async function switchList(id){if(id===state.listId)return;state.listId=id;localStorage.setItem('minhaFarmaciaListId',id);if(state.remote){try{await loadRemote()}catch(e){toast(`Não foi possível abrir a lista: ${e.message}`,true)}}else{state.meds=state.meds.filter(m=>m.listId===id);state.purchases=state.purchases.filter(x=>x.listId===id);state.reminders=state.reminders.filter(x=>state.meds.some(m=>m.id===x.medId));state.movements=state.movements.filter(x=>x.listId===id)}render()}
async function addMovement(row){row.id=uid();row.listId=state.listId;row.occurredAt=new Date().toISOString();row.medicationName=row.medicationName||state.meds.find(m=>m.id===row.medId)?.name||'Medicamento';state.movements.unshift(row);if(state.remote){const med=state.meds.find(m=>m.id===row.medId);const payload={user_id:state.user.id,list_id:state.listId,medication_id:med?.remoteId||null,medication_name:row.medicationName,kind:row.kind,quantity_delta:row.quantityDelta??null,before_quantity:row.beforeQuantity??null,after_quantity:row.afterQuantity??null,notes:row.notes||'',occurred_at:row.occurredAt};const {data,error}=await state.client.from('stock_movements').insert(payload).select('*').single();if(error)toast(`Movimentação não sincronizada: ${error.message}`,true);else Object.assign(row,{id:data.id})}else persist()}
function reminderEligible(m,kind){const days=getDays(m);return kind==='prescription'?needsPrescription(m)&&days<=Number(m.prescriptionDays||0):days<=Number(m.lowDays||0)}
function syncLocalReminders(){let changed=false;for(const m of state.meds){for(const kind of ['prescription','purchase']){const eligible=reminderEligible(m,kind);let r=state.reminders.find(x=>x.medId===m.id&&x.kind===kind);if(!r&&eligible){r={id:uid(),medId:m.id,kind,status:'pending',isEligible:true};state.reminders.push(r);changed=true}else if(r){if(eligible&&r.status==='completed'&&!r.isEligible){r.status='pending';r.completedAt=null;r.lastNotifiedAt=null;changed=true}if(r.isEligible!==eligible){r.isEligible=eligible;changed=true}}}}return changed}
function completeReminderLocal(r){r.status='completed';r.completedAt=new Date().toISOString();r.isEligible=reminderEligible(state.meds.find(m=>m.id===r.medId)||{},r.kind);r.lastNotifiedAt=null}
function remindersPage(){const pending=state.reminders.filter(r=>r.status==='pending').sort((a,b)=>{const rank={purchase:0,prescription:1};return rank[a.kind]-rank[b.kind]});return `<section class="panel"><div class="panel-head"><div><h2 class="panel-title">Ações pendentes</h2><p class="panel-subtitle">Cada aviso continua até você confirmar no app.</p></div><span class="status-pill ${pending.length?'warn':''}">${pending.length} pendente${pending.length===1?'':'s'}</span></div>${pending.length?`<div class="reminder-list">${pending.map(r=>{const m=state.meds.find(x=>x.id===r.medId);if(!m)return '';const purchase=r.kind==='purchase';return `<article class="reminder-card"><div class="reminder-mark ${purchase?'critical':''}">${purchase?'＋':'▤'}</div><div class="reminder-copy"><strong>${purchase?'Comprar':'Pedir receita'} · ${esc(m.name)}</strong><p>${purchase?`Estoque estimado: ${fmtQty(getRemaining(m))} ${esc(unit(m))} (${daysText(getDays(m))}). Ao confirmar a compra, informe a quantidade para atualizar o saldo.`:'Marque quando já tiver solicitado a receita.'}</p></div><button class="primary-button compact" data-action="${purchase?'reminder-purchase':'reminder-prescription'}" data-id="${esc(m.id)}" data-reminder-id="${esc(r.id)}">${purchase?'Registrar compra':'Já pedi a receita'}</button></article>`}).join('')}</div>`:`<div class="alert-empty">Nenhuma ação pendente. Quando um medicamento atingir os limites cadastrados, o lembrete aparecerá aqui.</div>`}</section><p class="helper">Os lembretes de receita e de compra são independentes. No Telegram, cada pendência é reenviada no horário programado até ser confirmada.</p>`}
function toast(message,error=false){const t=document.createElement('div');t.className='toast'+(error?' error':'');t.textContent=message;$('#toast-root').append(t);setTimeout(()=>t.remove(),3400)}
function medIcon(i){return ['✳','◉','✦','◈','⊙'][i%5]}
function progress(m){let d=getDays(m);if(!Number.isFinite(d))return 100;const threshold=Math.max(Number(m.lowDays)||0,needsPrescription(m)?Number(m.prescriptionDays)||0:0);return Math.max(0,Math.min(100,(d/Math.max(threshold*2,30))*100))}
function medRow(m,i){const st=statusFor(m),d=getDays(m);return `<div class="med-row"><div class="med-name-wrap"><div class="med-avatar ${m.color||''}">${medIcon(i)}</div><div style="min-width:0"><button class="med-name med-name-button" type="button" data-action="edit-med" data-id="${esc(m.id)}" aria-label="Editar ${esc(m.name)}">${esc(m.name)}</button><div class="med-detail">${esc(m.presentation||`${fmtQty(m.daily)} ${unit(m)}/dia`)}</div></div></div><div class="stock-area"><div class="days-label"><strong>${fmtQty(getRemaining(m))} ${esc(unit(m))}</strong> restantes · ${daysText(d)}</div><div class="stock-bar"><div class="stock-fill ${st.cls}" style="width:${progress(m)}%"></div></div></div><span class="status-pill ${st.cls}">${st.label}</span></div>`}
function dashboard(){const meds=state.meds,total=meds.length,need=meds.filter(needsAttention).length,low=meds.filter(m=>getDays(m)<=m.lowDays).length,days=meds.length?Math.max(0,Math.min(...meds.map(getDays))):0;const alerts=meds.filter(needsAttention).sort((a,b)=>getDays(a)-getDays(b));const upcoming=meds.filter(m=>getDays(m)>Math.max(Number(m.lowDays)||0,needsPrescription(m)?Number(m.prescriptionDays)||0:0)).sort((a,b)=>getDays(a)-getDays(b)).slice(0,3);return `<div class="summary-grid"><button type="button" class="summary-card interactive-card" data-go="medicamentos"><span class="metric-icon">▤</span><div class="card-label">Medicamentos ativos</div><div class="card-number">${total}</div><div class="card-foot">Na lista selecionada</div></button><button type="button" class="summary-card interactive-card" data-go="medicamentos" data-dashboard-filter="atencao"><span class="metric-icon orange">◷</span><div class="card-label">Precisam de atenção</div><div class="card-number">${need}</div><div class="card-foot">${low} com estoque baixo · abrir</div></button><button type="button" class="summary-card interactive-card" data-go="medicamentos" data-dashboard-filter="atencao"><span class="metric-icon blue">⌁</span><div class="card-label">Próximo estoque a acabar</div><div class="card-number">${total?daysText(days):'—'}</div><div class="card-foot">Abrir medicamentos</div></button><button type="button" class="summary-card interactive-card" data-go="historico"><span class="metric-icon">✓</span><div class="card-label">Compras registradas</div><div class="card-number">${state.purchases.length}</div><div class="card-foot">Abrir compras e movimentações</div></button></div><div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Seus medicamentos</h2><p class="panel-subtitle">Saldo estimado com base no consumo diário</p></div><button class="text-action" data-go="medicamentos">Ver todos →</button></div>${meds.length?`<div class="med-list">${meds.slice(0,5).map(m=>medRow(m,meds.indexOf(m))).join('')}</div>`:emptyMed()}</section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Precisa de atenção</h2><p class="panel-subtitle">Receita e reposição chegando</p></div><span class="metric-icon orange" style="position:static">♧</span></div>${alerts.length?`<div class="alert-list">${alerts.slice(0,3).map(m=>`<div class="alert-item ${getDays(m)<=m.lowDays?'critical':''}"><span class="alert-symbol">${getDays(m)<=m.lowDays?'!':'◷'}</span><div class="alert-copy"><strong>${esc(m.name)} · ${getDays(m)<=m.lowDays?'Estoque baixo':'Pedir receita'}</strong><p>Estimativa: ${daysText(getDays(m))} restantes. ${getDays(m)<=m.lowDays?'Considere verificar a reposição.':'Este medicamento está marcado como dependente de receita.'}</p></div></div>`).join('')}</div>`:`<div class="alert-empty">${meds.length?'Tudo tranquilo por enquanto. Avisaremos aqui conforme os limites cadastrados.':'Cadastre um medicamento para ver seus alertas.'}</div>`}</section></div><section class="panel"><div class="panel-head"><div><h2 class="panel-title">No horizonte</h2><p class="panel-subtitle">Estimativa dos próximos medicamentos a repor</p></div><button class="text-action" data-go="historico">Ver histórico →</button></div>${upcoming.length?upcoming.map(m=>`<div class="upcoming-row"><span class="calendar-chip">${Math.ceil(getDays(m))}<small> DIAS</small></span><div class="upcoming-copy"><strong>${esc(m.name)}</strong><span>${fmtQty(getRemaining(m))} ${esc(unit(m))} estimados</span></div><span class="upcoming-days">${daysText(getDays(m))}</span></div>`).join(''):`<div class="alert-empty">${meds.length?'Os demais estoques estão confortáveis.':'Seu resumo aparecerá aqui após cadastrar um medicamento.'}</div>`}</section>`}
function emptyMed(){return `<div class="empty-state"><div class="empty-icon">＋</div><h3>Comece seu acompanhamento</h3><p>Cadastre um medicamento para acompanhar o saldo estimado, a previsão de reposição e a renovação de receita.</p><button class="primary-button" data-action="new-med">＋ Novo medicamento</button></div>`}
function medicinePage(){const meds=state.meds.filter(m=>state.filter==='todos'||(state.filter==='atencao'?needsAttention(m):!needsAttention(m)));return `<section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">Medicamentos cadastrados</h2><p class="panel-subtitle">O saldo é estimado automaticamente com o passar dos dias.</p></div><button class="primary-button compact" data-action="new-med">＋ Adicionar</button></div><div class="filters"><button class="filter-btn ${state.filter==='todos'?'selected':''}" data-filter="todos">Todos (${state.meds.length})</button><button class="filter-btn ${state.filter==='atencao'?'selected':''}" data-filter="atencao">Precisam de atenção (${state.meds.filter(needsAttention).length})</button><button class="filter-btn ${state.filter==='em-dia'?'selected':''}" data-filter="em-dia">Em dia (${state.meds.filter(m=>!needsAttention(m)).length})</button></div><div style="overflow:auto;margin-top:13px"><table class="full-table"><thead><tr><th>Medicamento</th><th>Estoque estimado</th><th>Consumo diário</th><th>Previsão</th><th>Status</th><th>Ações</th></tr></thead><tbody>${meds.map(m=>{let st=statusFor(m);return `<tr><td><button class="med-name med-name-button" type="button" data-action="edit-med" data-id="${esc(m.id)}" aria-label="Editar ${esc(m.name)}">${esc(m.name)}</button><div class="med-detail">${esc(m.presentation||'')}</div></td><td>${fmtQty(getRemaining(m))} ${esc(unit(m))}</td><td>${fmtQty(m.daily)} ${esc(unit(m))}/dia ${m.paused?'(pausado)':''}</td><td>${daysText(getDays(m))}</td><td><span class="status-pill ${st.cls}">${st.label}</span></td><td><div class="inline-actions"><button class="small-action" data-action="purchase" data-id="${esc(m.id)}">＋ Compra</button><button class="small-action" data-action="toggle-prescription" data-id="${esc(m.id)}">${needsPrescription(m)?'✓ Precisa receita':'Sem receita'}</button><button class="small-action" data-action="edit-med" data-id="${esc(m.id)}">Editar</button><button class="small-action" data-action="delete-med" data-id="${esc(m.id)}">Remover</button></div></td></tr>`}).join('')}</tbody></table></div>${!meds.length?emptyMed():''}</section><p class="helper">A previsão usa o consumo diário que você cadastrou. Ela não confirma doses tomadas; ajuste o saldo se sua rotina mudar ou o medicamento for pausado.</p>`}
function historyPage(){const events=[...state.purchases.map(x=>({kind:'purchase',occurredAt:(x.purchasedAt||todayISO())+'T12:00:00',medName:state.meds.find(m=>m.id===x.medId)?.name||x.medName||'Medicamento',quantityDelta:+x.quantity,notes:x.notes||'',price:x.price})),...state.movements.filter(x=>x.kind!=='purchase').map(x=>({...x,occurredAt:x.occurredAt||x.occurred_at,medName:x.medName||x.medication_name}))].sort((a,b)=>String(b.occurredAt).localeCompare(String(a.occurredAt)));return `<section class="panel table-panel"><div class="panel-head"><div><h2 class="panel-title">Histórico de movimentações · ${esc(currentList()?.name||'Lista')}</h2><p class="panel-subtitle">Compras e alterações de estoque desta lista</p></div><button class="primary-button compact" data-action="purchase-choose">＋ Registrar compra</button></div>${events.length?`<div style="overflow:auto"><table class="full-table"><thead><tr><th>Data</th><th>Tipo</th><th>Medicamento</th><th>Variação</th><th>Saldo após</th><th>Detalhes</th></tr></thead><tbody>${events.map(x=>{const date=String(x.occurredAt||'').slice(0,10);return `<tr><td>${date?new Intl.DateTimeFormat('pt-BR').format(new Date(date+'T12:00:00')):'—'}</td><td><strong>${x.kind==='purchase'?'Compra':x.kind==='adjustment'?'Ajuste':x.kind==='created'?'Cadastro':x.kind==='removed'?'Remoção':x.kind==='prescription_confirmed'?'Receita confirmada':'Movimentação'}</strong></td><td>${esc(x.medName||x.medication_name||'—')}</td><td>${x.quantityDelta!=null||x.quantity_delta!=null?fmtQty(Number(x.quantityDelta??x.quantity_delta)):'—'}</td><td>${x.afterQuantity!=null||x.after_quantity!=null?fmtQty(Number(x.afterQuantity??x.after_quantity)):'—'}</td><td>${esc(x.notes||'')}</td></tr>`}).join('')}</tbody></table></div>`:`<div class="empty-state"><div class="empty-icon">◷</div><h3>Nenhuma movimentação registrada</h3><p>Compras e ajustes feitos nesta lista aparecerão aqui.</p>${state.meds.length?'<button class="primary-button" data-action="purchase-choose">＋ Registrar compra</button>':''}</div>`}</section>`}
function currentList(){return state.lists.find(l=>l.id===state.listId)}
function settingsPage(){return `<div class="settings-grid"><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Listas de pessoas</h2><p class="panel-subtitle">Cada lista tem medicamentos, lembretes e histórico próprios.${state.user?'':' Entre na conta para usar várias listas.'}</p></div><button class="primary-button compact" data-action="new-list">＋ Criar lista</button></div>${state.lists.map(l=>`<div class="setting-row"><div><strong>${esc(l.name)} ${l.id===state.listId?"· aberta":""}</strong><p>${l.id===state.listId?"Lista selecionada":"Toque em trocar para abrir esta lista"}</p></div><div class="inline-actions"><button class="secondary-button" data-action="switch-list" data-id="${esc(l.id)}">Abrir</button><button class="secondary-button" data-action="rename-list" data-id="${esc(l.id)}">Renomear</button><button class="danger-button" data-action="delete-list" data-id="${esc(l.id)}">Excluir</button></div></div>`).join("")}</section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Lembretes do medicamento</h2><p class="panel-subtitle">Os limites são definidos para cada item</p></div></div><div class="setting-row"><div><strong>Alertas dentro do app</strong><p>Mostra avisos no resumo ao atingir seus limites.</p></div><span class="status-pill">Ativo</span></div><div class="setting-row"><div><strong>Telegram</strong><p>Notificações externas precisam da função segura configurada no servidor.</p></div><button class="secondary-button" data-action="telegram-setup">Configurar Telegram</button></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Conta e dados</h2><p class="panel-subtitle">Escolha como salvar suas informações</p></div></div><div class="setting-row"><div><strong>Conta conectada</strong><p>Seus dados privados são sincronizados com a conta Supabase.</p></div><div class="inline-actions"><button class="secondary-button" data-action="link-google">Vincular Google</button></div></div><div class="setting-row"><div><strong>Privacidade</strong><p>Não salve dados de saúde desnecessários. Configure Row Level Security no Supabase antes de conectar.</p></div><span class="status-pill">Pessoal</span></div></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Como a previsão funciona</h2><p class="panel-subtitle">Transparência no cálculo do saldo</p></div></div><p class="helper">O saldo exibido diminui conforme o consumo diário cadastrado e o tempo decorrido desde a data-base. Registrar uma compra soma a quantidade ao saldo. O cálculo é apenas uma estimativa de organização; não verifica se uma dose foi tomada e não recomenda alterações na prescrição.</p></section><section class="panel"><div class="panel-head"><div><h2 class="panel-title">Dados deste navegador</h2><p class="panel-subtitle">Exportar ou apagar os dados salvos localmente</p></div></div><div class="setting-row"><div><strong>Exportar cópia</strong><p>Baixe uma cópia em JSON das informações locais.</p></div><button class="secondary-button" data-action="export">Exportar</button></div><div class="setting-row"><div><strong>Apagar dados locais</strong><p>Esta ação não pode ser desfeita neste navegador.</p></div><button class="danger-button" data-action="clear-local">Apagar</button></div></section></div>`}
function render(){if(!state.user){authScreen();return}document.body.classList.remove('auth-required');const select=$('#list-select');if(select){select.innerHTML=state.lists.map(l=>`<option value="${esc(l.id)}" ${l.id===state.listId?'selected':''}>${esc(l.name)}</option>`).join('');select.classList.toggle('hidden',!state.user)}const remindersChanged=syncLocalReminders();if(!state.remote)localStorage.setItem('minhaFarmaciaReminders',JSON.stringify(state.reminders));else if(remindersChanged)saveRemote();updateHeader();const root=$('#page-content');if(state.page==='inicio')root.innerHTML=dashboard();if(state.page==='medicamentos')root.innerHTML=medicinePage();if(state.page==='historico')root.innerHTML=historyPage();if(state.page==='configuracoes')root.innerHTML=settingsPage();if(state.page==='lembretes')root.innerHTML=remindersPage();$('#page-crumb').textContent=({inicio:'Visão geral',medicamentos:'Medicamentos',historico:'Histórico',lembretes:'Lembretes',configuracoes:'Configurações'})[state.page]||'Visão geral';$$('.nav-item[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===state.page));}
function field(label,name,type='text',value='',opts={}){return `<div class="field ${opts.full?'full':''}"><label for="f-${name}">${label}</label>${opts.options?`<select id="f-${name}" name="${name}" ${opts.required?'required':''}>${opts.options.map(x=>`<option value="${esc(x.value)}" ${String(x.value)===String(value)?'selected':''}>${esc(x.label)}</option>`).join('')}</select>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${opts.required?'required':''} ${opts.min!==undefined?`min="${opts.min}"`:''} ${opts.step?`step="${opts.step}"`:''} ${opts.placeholder?`placeholder="${opts.placeholder}"`:''} />`}${opts.hint?`<span class="field-hint">${opts.hint}</span>`:''}</div>`}
function showModal(title,subtitle,body,onSubmit,submit='Salvar'){const root=$('#modal-root');root.innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>${title}</h2><p>${subtitle}</p></div><button type="button" class="close-modal" data-action="close">×</button></div><form id="active-form">${body}<div class="modal-actions"><button class="secondary-button" type="button" data-action="close">Cancelar</button><button class="primary-button" type="submit">${submit}</button></div></form></section></div>`;$('.modal-backdrop',root).addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop'))closeModal()});$('#active-form',root).addEventListener('submit',async e=>{e.preventDefault();await onSubmit(Object.fromEntries(new FormData(e.currentTarget)));});setTimeout(()=>$('.modal input',root)?.focus(),50)}
function closeModal(){$('#modal-root').innerHTML=''}
function medForm(existing){const m=existing||{};return `<div class="form-grid">${field('Nome do medicamento','name','text',m.name||'',{required:true,full:true,placeholder:'Ex.: medicamento prescrito'})}${field('Apresentação ou dose (opcional)','presentation','text',m.presentation||'',{full:true,placeholder:'Ex.: comprimido • 50 mg'})}${field('Quantidade atual','quantity','number',existing?fmtQty(getRemaining(m)):30,{required:true,min:0,step:'0.1',hint:'Saldo estimado hoje'})}${field('Unidade de controle','unit','text',m.unit||'comprimidos',{required:true,placeholder:'comprimidos, ml, cápsulas…'})}${field('Consumo por dia','daily','number',m.daily??1,{required:true,min:0,step:'0.1',hint:'Conforme sua orientação profissional'})}${field('Data-base do saldo','baseDate','date',todayISO(),{required:true,hint:'A partir desta data, descontamos o consumo previsto.'})}<div class="field full"><label style="display:flex;align-items:center;gap:9px"><input type="checkbox" name="needsPrescription" ${needsPrescription(m)?'checked':''} style="width:auto"> Este medicamento precisa de receita</label><span class="field-hint">Só medicamentos marcados aqui terão alertas para pedir ou renovar receita.</span></div>${field('Avisar para pedir receita com quantos dias','prescriptionDays','number',m.prescriptionDays??14,{required:true,min:0,step:'1'})}${field('Avisar estoque baixo com quantos dias','lowDays','number',m.lowDays??7,{required:true,min:0,step:'1'})}<div class="field full"><label style="display:flex;align-items:center;gap:9px"><input type="checkbox" name="paused" ${m.paused?'checked':''} style="width:auto"> Pausar desconto automático temporariamente</label><span class="field-hint">Enquanto pausado, o saldo não diminui pela previsão diária.</span></div></div>`}
function openMed(id){const old=state.meds.find(m=>String(m.id)===String(id));showModal(old?'Editar medicamento':'Adicionar medicamento',old?'Ajuste o cadastro e o saldo-base.':'Informe os dados para calcular uma previsão de estoque.',medForm(old),async d=>{const wasPaused=!!old?.paused,willPause=$('#active-form [name=paused]')?.checked||false;let m={...(old||{}),name:d.name.trim(),presentation:d.presentation.trim(),unit:d.unit.trim()||'unidades',needsPrescription:$('#active-form [name=needsPrescription]')?.checked===true,initial:Number(d.quantity),baseRemaining:Number(d.quantity),daily:Number(d.daily),baseDate:d.baseDate||todayISO(),startedAt:d.baseDate||todayISO(),prescriptionDays:Number(d.prescriptionDays),lowDays:Number(d.lowDays),paused:willPause,pausedDaysOffset:old?.pausedDaysOffset||0,color:old?.color||['','amber','rose'][state.meds.length%3]};if(old&&wasPaused!==willPause){const elapsed=dateDiff(old.baseDate||todayISO(),todayISO());if(wasPaused&&!willPause)m.pausedDaysOffset=(Number(old.pausedDaysOffset)||0)+elapsed;else if(!wasPaused&&willPause)m.pausedDaysOffset=Number(old.pausedDaysOffset)||0}if(old){const before=getRemaining(old);Object.assign(old,m);if(Math.abs(before-Number(d.quantity))>0.0001)addMovement({kind:'adjustment',medId:old.id,quantityDelta:Number(d.quantity)-before,beforeQuantity:before,afterQuantity:Number(d.quantity),notes:'Ajuste manual de saldo'});}else{m.id=uid();m.listId=state.listId;state.meds.push(m);addMovement({kind:'created',medId:m.id,quantityDelta:Number(d.quantity),beforeQuantity:0,afterQuantity:Number(d.quantity),notes:'Medicamento cadastrado'})}persist();closeModal();render();toast(old?'Cadastro atualizado.':'Medicamento adicionado.')})}
function openPurchase(id,reminderId){const meds=id?state.meds.filter(m=>m.id===id):state.meds;if(!meds.length){toast('Cadastre um medicamento primeiro.');return}const selected=id||meds[0].id;const options=meds.map(m=>({value:m.id,label:m.name}));showModal('Registrar compra','A quantidade comprada será somada ao saldo estimado.',`<div class="form-grid">${field('Medicamento','medId','text',selected,{required:true,full:true,options})}${field('Quantidade comprada','quantity','number','30',{required:true,min:0.1,step:'0.1'})}${field('Data da compra','purchasedAt','date',todayISO(),{required:true})}${field('Valor (opcional)','price','number','',{min:0,step:'0.01',placeholder:'0,00'})}${field('Observação (opcional)','notes','text','',{full:true,placeholder:'Ex.: farmácia ou detalhes da compra'})}</div>`,async d=>{const m=state.meds.find(x=>x.id===d.medId);if(!m)return;const qty=Number(d.quantity);if(qty<=0)return;const beforeBuy=getRemaining(m),boughtAt=d.purchasedAt||todayISO(),elapsed=dateDiff(boughtAt,todayISO()),remaining=Math.max(0,beforeBuy+qty-elapsed*(m.paused?0:(+m.daily||0)));m.baseRemaining=remaining;m.baseDate=todayISO();m.initial=remaining;const p={id:`local-${uid()}`,medId:m.id,medName:m.name,quantity:qty,purchasedAt:boughtAt,price:d.price?Number(d.price):null,notes:d.notes.trim(),unit:m.unit,listId:state.listId};state.purchases.push(p);if(!state.remote)addMovement({kind:'purchase',medId:m.id,quantityDelta:qty,beforeQuantity:beforeBuy,afterQuantity:remaining,notes:d.notes.trim()});const reminder=state.reminders.find(r=>r.id===reminderId)||state.reminders.find(r=>r.medId===m.id&&r.kind==='purchase'&&r.status==='pending');if(reminder)completeReminderLocal(reminder);persist();closeModal();render();toast(`${fmtQty(qty)} ${m.unit} adicionados ao saldo.`)})}
function authScreen(message='',isError=false){document.body.classList.add('auth-required');const root=$('#auth-screen');if(!root)return;if(!state.sessionReady&&message==='') {root.innerHTML='<div class="auth-layout"><div class="auth-loading"><span class="brand-mark">✳</span><br>Verificando seu acesso…</div></div>';return}const signup=state.authMode==='signup';root.innerHTML=`<div class="auth-layout"><a class="auth-brand" href="#login"><span class="brand-mark">✳</span><span>minha<span class="brand-light">farmácia</span></span></a><section class="auth-card"><h1>${signup?'Crie sua conta':'Bem-vindo à sua farmácia'}</h1><p class="auth-intro">${signup?'Crie uma conta para manter suas listas e lembretes seguros.':'Entre para acessar seus medicamentos, listas e lembretes.'}</p>${message?`<p class="auth-notice ${isError?'auth-error':''}" role="status">${esc(message)}</p>`:''}<button type="button" class="google-button" data-auth-action="google">G&nbsp;&nbsp; Continuar com Google</button><div class="auth-divider">ou ${signup?'crie sua conta':'entre com e-mail'}</div><form id="login-form"><div class="field"><label for="auth-email">E-mail</label><input id="auth-email" name="email" type="email" autocomplete="email" placeholder="voce@exemplo.com" required></div><div class="field"><label for="auth-password">Senha</label><input id="auth-password" name="password" type="password" autocomplete="${signup?'new-password':'current-password'}" required minlength="6"></div><label class="auth-remember"><input id="remember-device" type="checkbox" ${localStorage.getItem('minhaFarmaciaRememberDevice')==='true'?'checked':''}><span><strong>Manter conectado neste dispositivo</strong><br>Não marque em aparelhos compartilhados.</span></label><button class="primary-button auth-submit" type="submit">${signup?'Criar conta':'Entrar'}</button><div class="auth-secondary">${signup?'<span></span>':'<button type="button" class="text-action" data-auth-action="forgot">Esqueci minha senha</button>'}<button type="button" class="text-action auth-mode-link" data-auth-action="toggle">${signup?'Já tenho conta':'Criar conta'}</button></div></form></section><p class="auth-footer">Seus dados ficam associados à sua conta. A aplicação é para organização e não substitui orientação profissional.</p></div>`;if(!message)setTimeout(()=>$('#auth-email')?.focus(),30)}
function authLoading(){document.body.classList.add('auth-required');$('#auth-screen').innerHTML='<div class="auth-layout"><div class="auth-loading"><span class="brand-mark">✳</span><br>Carregando seus dados…</div></div>'}
let sessionActivation=null;async function activateSession(user){if(!user)return;if(state.user?.id===user.id&&state.remote&&state.sessionReady)return;if(sessionActivation?.id===user.id)return sessionActivation.promise;const promise=(async()=>{authLoading();state.user=user;state.remote=true;try{loadLocal();await loadRemote();await migrateLocalDataOnce();await loadRemote();state.sessionReady=true;updateProfile();render();}catch(e){state.user=null;state.remote=false;state.sessionReady=true;authScreen(`Não foi possível carregar sua conta: ${e.message}`,true)}})();sessionActivation={id:user.id,promise};try{await promise}finally{if(sessionActivation?.promise===promise)sessionActivation=null}}
async function submitLogin(e){e.preventDefault();if(!state.client){authScreen('O acesso ainda não está configurado. Verifique a conexão do site com o Supabase.',true);return}const form=e.currentTarget;const email=form.querySelector('[name=email]').value.trim();const password=form.querySelector('[name=password]').value;const remember=$('#remember-device').checked;localStorage.setItem('minhaFarmaciaRememberDevice',String(remember));const button=form.querySelector('[type=submit]');button.disabled=true;button.textContent=state.authMode==='signup'?'Criando conta…':'Entrando…';try{if(state.authMode==='signup'){const {data,error}=await state.client.auth.signUp({email,password});if(error)throw error;if(data.session){await activateSession(data.user);toast('Conta criada.')}else{state.authMode='login';authScreen('Conta criada. Confira seu e-mail para confirmar o acesso.');}}else{const {data,error}=await state.client.auth.signInWithPassword({email,password});if(error)throw error;await activateSession(data.user);toast('Sessão iniciada.')}}catch(error){authScreen(error.message,true)}finally{if(document.body.classList.contains('auth-required')){const next=$('#login-form [type=submit]');if(next)next.disabled=false}}}
async function startGoogle(){const {error}=await state.client.auth.signInWithOAuth({provider:'google',options:{redirectTo:location.origin+location.pathname,queryParams:{prompt:'select_account'}}});if(error)toast(error.message,true)}
async function linkGoogle(){if(!state.user){authModal();return}const {error}=await state.client.auth.linkIdentity({provider:'google',options:{redirectTo:location.origin+location.pathname,queryParams:{prompt:'select_account'}}});if(error)toast(error.message,true)}
async function changeRecoveredPassword(){showModal('Criar nova senha','Escolha uma senha nova para sua conta.',field('Nova senha','newPassword','password','',{required:true,full:true}),async d=>{const {error}=await state.client.auth.updateUser({password:d.newPassword});if(error){toast(error.message,true);return}closeModal();history.replaceState({},document.title,location.pathname);toast('Senha atualizada com sucesso.')},'Salvar senha')}
async function forgotPassword(){const email=$('#auth-email')?.value.trim();if(!email){authScreen('Digite seu e-mail primeiro.',true);return}const {error}=await state.client.auth.resetPasswordForEmail(email,{redirectTo:location.origin+location.pathname});if(error)authScreen(error.message,true);else authScreen('Enviamos um link de recuperação, se o e-mail estiver cadastrado.')}

function updateProfile(){if(state.user){$('#profile-name').textContent=state.user.user_metadata?.full_name||state.user.email||'Minha conta';$('#profile-status').textContent='Sincronizado pelo Supabase';$('#auth-action').textContent='↪';}else{$('#profile-name').textContent='Modo de demonstração';$('#profile-status').textContent='Dados salvos neste aparelho';$('#auth-action').textContent='⋯'}}
function listModal(existing){showModal(existing?'Renomear lista':'Criar lista',existing?'Altere o nome desta lista.':'Ex.: Lucas, Mãe ou Pai.',field('Nome da lista','name','text',existing?.name||'',{required:true,full:true,placeholder:'Nome da pessoa'}),async d=>{const name=d.name.trim();if(!name)return;if(existing)existing.name=name;else{const item={id:`local-${uid()}`,name};state.lists.push(item);if(state.remote){const {data,error}=await state.client.from('medication_lists').insert({user_id:state.user.id,name}).select('id').single();if(error){state.lists=state.lists.filter(x=>x!==item);toast(error.message,true);return}item.id=data.id}state.listId=item.id}persist();closeModal();render();toast(existing?'Lista renomeada.':'Lista criada.')})}
async function deleteList(id){if(!state.remote){toast('Entre na conta para administrar listas sincronizadas.',true);return}const l=state.lists.find(x=>x.id===id);if(!l)return;if(state.lists.length<2){toast('Mantenha pelo menos uma lista na conta.',true);return}if(!confirm(`Excluir a lista “${l.name}” e os dados associados? Esta ação não pode ser desfeita.`))return;if(state.remote){const {error}=await state.client.from('medication_lists').delete().eq('id',id);if(error){toast(error.message,true);return}}state.lists=state.lists.filter(x=>x.id!==id);if(state.listId===id)state.listId=state.lists[0].id;persist();if(state.remote)await loadRemote();render();toast('Lista excluída.')}
async function onAction(action,id,reminderId){if(action==='google-login'){startGoogle();return}if(action==='link-google'){linkGoogle();return}if(action==='forgot-password'){forgotPassword();return}if(action==='change-password'){changeRecoveredPassword();return}if(action==='new-list'){if(!state.user){toast('Entre na sua conta antes de criar listas para pessoas diferentes.',true);authModal();return}listModal();return}if(action==='rename-list'){listModal(state.lists.find(l=>l.id===id));return}if(action==='switch-list'){switchList(id);return}if(action==='delete-list'){deleteList(id);return}if(action==='close')closeModal();if(action==='new-med')openMed();if(action==='edit-med')openMed(id);if(action==='toggle-prescription'){const med=state.meds.find(m=>String(m.id)===String(id));if(med){med.needsPrescription=!needsPrescription(med);persist();render();toast(med.needsPrescription?'Alertas de receita ativados.':'Alertas de receita desativados.')}}if(action==='delete-med'){const med=state.meds.find(m=>m.id===id);if(med&&confirm(`Remover ${med.name} e o histórico de compras associado?`)){addMovement({kind:'removed',medId:med.id,medicationName:med.name,notes:'Medicamento removido'});if(state.remote&&med.remoteId){const {error}=await state.client.from('medications').delete().eq('id',med.remoteId);if(error){toast(error.message,true);return}}state.meds=state.meds.filter(m=>m.id!==id);state.purchases=state.purchases.filter(p=>p.medId!==id);persist();render();toast('Medicamento removido.')}}if(action==='purchase')openPurchase(id);if(action==='purchase-choose')openPurchase();if(action==='reminder-purchase'){openPurchase(id,reminderId)}if(action==='reminder-prescription'){const med=state.meds.find(m=>String(m.id)===String(id)),reminder=state.reminders.find(r=>r.id===reminderId);if(med&&reminder){completeReminderLocal(reminder);addMovement({kind:'prescription_confirmed',medId:med.id,notes:'Pedido de receita confirmado'});persist();render();toast('Pedido de receita confirmado.')}}if(action==='telegram-setup')telegramModal();if(action==='telegram-test'){testTelegram();return;}if(action==='export')exportData();if(action==='clear-local')clearLocal()}
function telegramModal(){showModal('Ativar lembretes no Telegram','Configure o bot no Supabase e teste a entrega por aqui.',`<p class="helper">No Telegram, crie um bot com <strong>@BotFather</strong>, envie <strong>/start</strong> para ele e obtenha seu chat ID com <strong>@userinfobot</strong>. Depois cadastre <strong>TELEGRAM_BOT_TOKEN</strong>, <strong>TELEGRAM_CHAT_ID</strong> e <strong>CRON_SECRET</strong> como secrets da Edge Function no Supabase, publique-a e configure o agendamento conforme o guia do projeto. O token fica somente no servidor.</p><button type="button" class="secondary-button" data-action="telegram-test" style="margin:0 0 14px">Testar envio no Telegram</button>${field('Limite de receita (padrão em dias)','prescriptionDefault','number',localStorage.getItem('minhaFarmaciaPrescriptionDefault')||'14',{min:0})}${field('Limite de estoque baixo (padrão em dias)','lowDefault','number',localStorage.getItem('minhaFarmaciaLowDefault')||'7',{min:0})}`,async d=>{localStorage.setItem('minhaFarmaciaPrescriptionDefault',d.prescriptionDefault);localStorage.setItem('minhaFarmaciaLowDefault',d.lowDefault);closeModal();toast('Limites padrão salvos. Os limites individuais dos medicamentos não foram alterados.')},'Salvar limites')}
async function testTelegram(){if(!state.client||!state.user){toast('Entre na sua conta Supabase antes de testar o Telegram.',true);return}const button=$('[data-action="telegram-test"]');if(button){button.disabled=true;button.textContent='Enviando…'}try{const {data,error}=await state.client.functions.invoke('telegram-reminders',{body:{action:'test'}});if(error)throw error;if(data?.error)throw new Error(data.error);toast('Mensagem de teste enviada ao Telegram.')}catch(e){toast(`Não foi possível testar o Telegram: ${e.message||'verifique a Edge Function e os secrets.'}`,true)}finally{if(button){button.disabled=false;button.textContent='Testar envio no Telegram'}}}
function exportData(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),medications:state.meds,purchases:state.purchases},null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`minha-farmacia-${todayISO()}.json`;a.click();URL.revokeObjectURL(a.href);toast('Cópia exportada.')}
function clearLocal(){if(!confirm('Apagar medicamentos e compras salvos neste navegador? Esta ação não pode ser desfeita.'))return;localStorage.removeItem('minhaFarmaciaMeds');localStorage.removeItem('minhaFarmaciaPurchases');localStorage.removeItem('minhaFarmaciaReminders');localStorage.removeItem('minhaFarmaciaMovements');state.meds=[];state.purchases=[];state.reminders=[];render();toast('Dados locais apagados.')}
document.addEventListener('change',e=>{if(e.target.matches('#list-select'))switchList(e.target.value);if(e.target.matches('#remember-device'))localStorage.setItem('minhaFarmaciaRememberDevice',String(e.target.checked))});document.addEventListener('submit',e=>{if(e.target.matches('#login-form'))submitLogin(e)});document.addEventListener('click',async e=>{const auth=e.target.closest('[data-auth-action]');if(auth){const action=auth.dataset.authAction;if(action==='google')startGoogle();if(action==='forgot')forgotPassword();if(action==='toggle'){state.authMode=state.authMode==='login'?'signup':'login';authScreen()}return}const page=e.target.closest('[data-page]');if(page&&state.user){state.page=page.dataset.page;closeDrawer();render();return}const go=e.target.closest('[data-go]');if(go&&state.user){state.page=go.dataset.go;if(go.dataset.dashboardFilter)state.filter=go.dataset.dashboardFilter;closeDrawer();render();return}const act=e.target.closest('[data-action]');if(act&&state.user){onAction(act.dataset.action,act.dataset.id,act.dataset.reminderId);return}const f=e.target.closest('[data-filter]');if(f&&state.user){state.filter=f.dataset.filter;render();return}const list=e.target.closest('#list-select');if(list&&state.user)switchList(list.value)});
$('#drawer-backdrop').addEventListener('click',closeDrawer);document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawer();if(state.user)closeModal()}});
$('#add-top').addEventListener('click',()=>{if(state.user)openMed()});$('#mobile-menu').addEventListener('click',()=>{if(state.user)setDrawer(!$('#sidebar').classList.contains('open'))});$('#alert-button').addEventListener('click',()=>{if(!state.user)return;state.page='inicio';render();document.querySelector('.alert-list')?.scrollIntoView({behavior:'smooth',block:'center'})});$('#auth-action').addEventListener('click',()=>{if(state.user)signOut()});async function signOut(){await state.client.auth.signOut();state.remote=false;state.user=null;state.meds=[];state.purchases=[];state.reminders=[];state.movements=[];state.lists=[];state.sessionReady=true;closeModal();authScreen('Você saiu da sua conta.');toast('Você saiu da conta.');}
const rememberStorage={getItem(key){try{return(localStorage.getItem('minhaFarmaciaRememberDevice')==='true'?localStorage:sessionStorage).getItem(key)}catch{return null}},setItem(key,value){try{const target=localStorage.getItem('minhaFarmaciaRememberDevice')==='true'?localStorage:sessionStorage;const other=target===localStorage?sessionStorage:localStorage;target.setItem(key,value);other.removeItem(key)}catch{}},removeItem(key){try{localStorage.removeItem(key);sessionStorage.removeItem(key)}catch{}}};
state.sessionReady=false;authScreen();if(window.APP_CONFIG?.SUPABASE_URL&&window.APP_CONFIG?.SUPABASE_ANON_KEY&&window.supabase?.createClient){state.client=window.supabase.createClient(window.APP_CONFIG.SUPABASE_URL,window.APP_CONFIG.SUPABASE_ANON_KEY,{auth:{storage:rememberStorage,persistSession:true,autoRefreshToken:true,detectSessionInUrl:true}});state.client.auth.onAuthStateChange((event,session)=>{if(event==='PASSWORD_RECOVERY'&&session?.user){activateSession(session.user).then(()=>changeRecoveredPassword());return}if(session?.user){if(state.user?.id!==session.user.id)activateSession(session.user)}else if(state.user){state.user=null;state.remote=false;state.sessionReady=true;state.meds=[];state.purchases=[];state.reminders=[];state.movements=[];state.lists=[];authScreen('Sua sessão foi encerrada.')}});state.client.auth.getSession().then(async({data,error})=>{if(error)throw error;if(data.session?.user){await activateSession(data.session.user)}else{state.sessionReady=true;authScreen()}}).catch(error=>{state.sessionReady=true;authScreen(`Não foi possível verificar o acesso: ${error.message}`,true)})}else{state.sessionReady=true;authScreen('O acesso ainda não está configurado. Verifique a conexão do site com o Supabase.',true)}setInterval(()=>{if(state.user&&!state.remote)render()},60000);
